//! Parity tests for `gpt_sovits_text::en_normalization` against golden fixtures
//! generated by `parity/en_normalization/gen_fixtures.py`.

use gpt_sovits_text::en_normalization::pyre::py_int;
use gpt_sovits_text::en_normalization::{Error, normalize};
use serde_json::{Value, json};

const HAND: &str = include_str!("fixtures/en_normalization/hand.jsonl");
const CORPUS: &str = include_str!("fixtures/en_normalization/corpus.jsonl");
const BULK: &str = include_str!("fixtures/en_normalization/bulk.jsonl");
const PY_INT: &str = include_str!("fixtures/en_normalization/py_int.jsonl");

/// Inputs whose Rust output is known to differ from Python. They must be
/// documented in `parity/README.md`; currently there are none.
const KNOWN_MISMATCHES: &[&str] = &[];

/// A Rust result in the fixture representation: `{"o": output}` or
/// `{"e": [type, message]}`.
fn to_json(r: Result<String, Error>) -> Value {
  match r {
    Ok(v) => json!({ "o": v }),
    Err(e) => json!({ "e": [e.name(), e.message()] }),
  }
}

fn check(name: &str, fixture: &str, f: impl Fn(&str) -> Result<String, Error>) {
  let mut n = 0;
  let mut mismatches = Vec::new();
  for line in fixture.lines() {
    let mut case: Value = serde_json::from_str(line).unwrap();
    let input = case["i"].as_str().unwrap().to_string();
    case.as_object_mut().unwrap().remove("i");
    n += 1;
    let got = to_json(f(&input));
    if got != case {
      if mismatches.len() < 20 {
        eprintln!("{name}: mismatch for {input:?}:\n  want {case}\n  got  {got}");
      }
      mismatches.push(input);
    }
  }
  let unexpected: Vec<_> = mismatches
    .iter()
    .filter(|m| !KNOWN_MISMATCHES.contains(&m.as_str()))
    .collect();
  eprintln!(
    "{name}: {} / {n} cases match ({} known mismatches)",
    n - mismatches.len(),
    mismatches.len() - unexpected.len()
  );
  assert!(n > 0, "{name}: empty fixture");
  assert!(
    unexpected.is_empty(),
    "{name}: {} unexpected mismatches",
    unexpected.len()
  );
}

#[test]
fn normalize_hand() {
  check("hand", HAND, normalize);
}

#[test]
fn normalize_corpus() {
  check("corpus", CORPUS, normalize);
}

#[test]
fn normalize_bulk() {
  check("bulk", BULK, normalize);
}

#[test]
fn py_int_matches_python_int() {
  check("py_int", PY_INT, py_int);
}

#[test]
fn known_mismatches_are_fixture_inputs() {
  // Every documented exception must still be a fixture input (and must still
  // mismatch, which `check` would report as a match otherwise).
  for m in KNOWN_MISMATCHES {
    let found = [HAND, CORPUS, BULK]
      .iter()
      .flat_map(|f| f.lines())
      .any(|l| serde_json::from_str::<Value>(l).unwrap()["i"] == *m);
    assert!(found, "known mismatch {m:?} is not a fixture input");
  }
}
